" y=\"592\" width=\"368\" height=\"104\" rx=\"12\" fill=\"rgba(255,255,255,0.03)\" stroke=\"rgba(255,255,255,0.12)\" stroke-width=\"1\"/>\n  <g stroke=\"#9DEBFF\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\" transform=\"translate(42,606)\">\n    <rect x=\"1\" y=\"3\" width=\"16\" height=\"14\" rx=\"2\"/><path d=\"M1 8 h16 M5 3 V1 M13 3 V1\"/>\n  </g>\n  <text x=\"72\" y=\"616\" font-size=\"12.5\" letter-spacing=\"1.5\" fill=\"#9DEBFF\">PROCESS · SCHEDULED EVENTS</text>\n  <text x=\"378\" y=\"616\" font-size=\"10.5\" letter-spacing=\"1\" fill=\"#9DEBFF\" text-anchor=\"end\">NO SILENT EXPIRY</text>\n  <text x=\"42\" y=\"638\" font-size=\"11\" fill=\"#F5F7FF\">mesh node keys expire at 180 days · agent auto-update</text>\n  <text x=\"42\" y=\"654\" font-size=\"11\" fill=\"#F5F7FF\">restart triggers re-login</text>\n  <text x=\"42\" y=\"672\" font-size=\"10.5\" fill=\"#64748B\">each expiry is a known calendar event with a computed</text>\n  <text x=\"42\" y=\"686\" font-size=\"10.5\" fill=\"#64748B\">successor date — not an incident diagnosed later</text>\n\n  <!-- bottom note -->\n  <text x=\"26\" y=\"730\" font-size=\"10.5\" fill=\"#64748B\">each layer fails independently of the others —</text>\n  <text x=\"26\" y=\"746\" font-size=\"10.5\" fill=\"#64748B\">privileged access requires a live, attentive operator</text>\n  <text x=\"26\" y=\"770\" font-size=\"10.5\" fill=\"#64748B\">residual risk narrows to session hijacking of an</text>\n  <text x=\"26\" y=\"786\" font-size=\"10.5\" fill=\"#64748B\">already-authenticated agent: a strictly smaller,</text>\n  <text x=\"26\" y=\"802\" font-size=\"10.5\" fill=\"#64748B\">more detectable surface</text>\n</svg>",
